mapper.select:
SELECT ma.*, st.student_name AS student_name, u1.real_name AS first_teacher_name, u2.real_name AS second_teacher_name, u3.real_name AS arbitration_teacher_name, pq.question_no, (SELECT image_url FROM answer_sheet_image WHERE answer_sheet_id = ma.answer_sheet_id LIMIT 1) AS answer_image_url FROM marking_arbitration ma LEFT JOIN student st ON ma.student_id = st.id LEFT JOIN sys_user u1 ON ma.first_teacher_id = u1.id LEFT JOIN sys_user u2 ON ma.second_teacher_id = u2.id LEFT JOIN sys_user u3 ON ma.arbitration_teacher_id = u3.id LEFT JOIN paper_question pq ON ma.question_id = pq.id WHERE ma.task_id = #{taskId}
AND ma.status = #{status}
ORDER BY ma.create_time DESC
